static bool argument(const char *text, uint32_t maximum, uint32_t *out) {
  const unsigned char *p = (const unsigned char *)text;
  const unsigned base = p[0] == '0' && (p[1] == 'x' || p[1] == 'X') ? 16U : 10U;
  if (base == 16U)
    p += 2;
  if (*p == 0U)
    return false;
  uint32_t value = 0;
  for (; *p != 0U; ++p) {
    unsigned digit;
    if (*p >= '0' && *p <= '9')
