    else if (base == 16U && *p >= 'A' && *p <= 'F')
      digit = (unsigned)(*p - 'A') + 10U;
    else
      return false;
    if (digit >= base || digit > maximum || value > (maximum - digit) / base)
      return false;
    value = value * base + digit;
  }
  *out = value;
  return true;
}
