    if (text[i] < '0' || text[i] > '9')
      return false;
    const unsigned digit = (unsigned)(text[i] - '0');
    if (digit > maximum || value > (maximum - digit) / 10U)
      return false;
    value = value * 10U + digit;
  }
  *out = value;
  return true;
}

