""",
        "SENSOR_SCALE": r"""
  const uint32_t scaled = (uint32_t)count * reference_mv;
  const uint32_t quotient = scaled / 4095U, remainder = scaled % 4095U;
  *out = (uint16_t)(quotient + (remainder * 2U >= 4095U ? 1U : 0U));
